// Font del sito (Newsreader per i titoli, Public Sans per il testo) incorporati
// come base64 per evitare problemi di caricamento file statici nelle funzioni
// serverless di Vercel. Ridotti ai soli caratteri latini (accenti, €, trattini).
import { Buffer } from 'buffer';

const SERIF_REGULAR_B64 = "";
const SERIF_MEDIUM_B64 = "";
const SERIF_ITALIC_B64 = "";
const SANS_REGULAR_B64 = "";
const SANS_SEMIBOLD_B64 = "";

export const serifRegular = Buffer.from(SERIF_REGULAR_B64, 'base64');
export const serifMedium = Buffer.from(SERIF_MEDIUM_B64, 'base64');
export const serifItalic = Buffer.from(SERIF_ITALIC_B64, 'base64');
export const sansRegular = Buffer.from(SANS_REGULAR_B64, 'base64');
export const sansSemiBold = Buffer.from(SANS_SEMIBOLD_B64, 'base64');
